"""GENERATED by make_prose_trainer.py from train_nuex3_v2.py -- edit that, not this.

Fine-tune NuExtract3 for grouping -- second configuration.

Three changes from the first run, each answering something it could not:

  * NuExtract3 is a Qwen3.5 hybrid: only 8 of 32 layers carry q/k/v/o, and the
    other 24 mix tokens through `linear_attn`, which the first run's module
    list never named. Grouping is a mixing operation, so 24 of the layers that
    perform it were frozen.
  * MLP cannot mix positions at all, yet it held 85% of the adapter. Its rank
    drops to 8 and the freed budget goes to the mixers.
  * `A_log` and `dt_bias` are 1,536 parameters setting how far back the
    recurrent state remembers. No matmul, so LoRA cannot reach them; they are
    unfrozen directly, at a tenth the learning rate.

Runs under torchrun, one process per card, DDP. `--probe N` runs N steps and
reports peak memory and per-group gradient norms instead of training.
"""
import argparse
import json
import math
import os
import random
import time
from pathlib import Path

import torch
import torch.distributed as dist
from liger_kernel.transformers.fused_linear_cross_entropy import (
    LigerFusedLinearCrossEntropyLoss,
)
from peft import LoraConfig, get_peft_model
from torch.nn.parallel import DistributedDataParallel as DDP
from torch.utils.data import DataLoader, Dataset, DistributedSampler
from transformers import AutoModelForImageTextToText, AutoTokenizer, BitsAndBytesConfig

ap = argparse.ArgumentParser()
ap.add_argument("--model", default="numind/NuExtract3")
ap.add_argument("--data", default="/home/james/train-data/train_curated.jsonl")
ap.add_argument("--out", default="/home/james/train-data/ckpt-nuex3-v2")
ap.add_argument("--rank", type=int, default=16, help="rank for the linear-attention mixers")
ap.add_argument("--mlp-rank", type=int, default=12)  # 8 would clip: v1 MLP used ~10-12 effective rank
ap.add_argument("--attn-rank", type=int, default=32)
ap.add_argument("--lr", type=float, default=1e-4)
ap.add_argument("--dropout", type=float, default=0.1, help="0.05 suited 25k examples; 3k needs more")
ap.add_argument("--slow-lr-div", type=float, default=10.0, help="divisor for directly-unfrozen tensors")
ap.add_argument("--no-conv-master", action="store_true",
                help="leave conv1d.weight as a bare bf16 parameter (it then "
                     "loses most of its updates to rounding)")
ap.add_argument("--accum", type=int, default=8)
ap.add_argument("--epochs", type=float, default=4.0)
ap.add_argument("--save-every", type=int, default=100)
ap.add_argument("--log-every", type=int, default=20)
ap.add_argument("--limit", type=int, default=0)
ap.add_argument("--max-tokens", type=int, default=4500,
                help="drop pairs longer than this. 7.66 GiB of card cannot hold the "
                     "backward pass for a 6.5k-token pair, and the canary proves it "
                     "in seconds -- but only after a full model load, so the filter "
                     "belongs here. No real table reaches this; the tail is synthetic.")
ap.add_argument("--no-linear-attn", action="store_true",
                help="reproduce the first run's module list, to isolate the change")
ap.add_argument("--no-unfreeze", action="store_true")
ap.add_argument("--probe", type=int, default=0)
ap.add_argument("--trackio-project", default="nuex3",
                help="trackio project; metrics go to a local sqlite db, no Space, "
                     "so nothing about the corpus leaves this machine")
ap.add_argument("--run-name", default="")
ap.add_argument("--no-trackio", action="store_true")
ap.add_argument("--stat-weight", type=float, default=1.0,
                help="multiply the loss on the statistic-type token "
                     "(the T/Z/F/P/R/B slot of a point); 1.0 = unchanged")
ap.add_argument("--init-from", default="",
                help="checkpoint dir to continue from; a fresh adapter otherwise")
ap.add_argument("--sched", default="onecycle", choices=("onecycle", "decay"),
                help="'decay' anneals from --lr without a warm-up climb, which "
                     "is what a continuation wants")
args = ap.parse_args()

local_rank = int(os.environ.get("LOCAL_RANK", 0))
world = int(os.environ.get("WORLD_SIZE", 1))
torch.cuda.set_device(local_rank)
if world > 1:
    dist.init_process_group("nccl")
main = local_rank == 0


class _NoTrack:
    """Metrics are worth having, not worth failing a four-hour run over."""

    def init(self, **kw):
        pass

    def log(self, *a, **kw):
        pass

    def finish(self):
        pass


class _Guard:
    """Metrics must not be able to end a run. An ImportError is not the only
    way trackio can fail four hours in, so every call is swallowed."""

    def __init__(self, inner):
        self._inner = inner

    def __getattr__(self, name):
        fn = getattr(self._inner, name, None)

        def call(*a, **kw):
            try:
                return fn(*a, **kw)
            except Exception as e:                      # noqa: BLE001
                print(f"  [trackio {name} failed: {e}]", flush=True)
        return call


try:
    import trackio as _trackio
    trackio = _Guard(_trackio)
except ImportError:
    trackio = _NoTrack()


def log(*a):
    if main:
        print(*a, flush=True)


tok = AutoTokenizer.from_pretrained(args.model)


# NuExtract3's native interface: a schema in a template block and the content
# in a document block. Passing `template=` switches the task from `content` to
# `structured`, which is the format the model was actually trained for. v1 sent
# raw text and an English instruction, which used none of it.
TEMPLATE = json.dumps({"space": ["MNI", "TAL"], "analyses": [{
    "name": "verbatim-string",
    "measure": ["voxels", "mm^3"],
    "points": [["number", "number", "number",
                ["T", "Z", "F", "P", "R", "B"], "number", "integer"]],
}]}, ensure_ascii=False)


def document(r):
    """What the model reads, in its own document block."""
    parts = [f"Title: {r.get('title') or ''}"]
    # Luna is given the article abstract (create_analyses.py). Withholding it
    # here made the two read different documents, and the abstract is where a
    # paper states its normalisation space and spells out what the table
    # abbreviates.
    if r.get("abstract"):
        parts.append(f"Abstract: {r['abstract']}")
    if r.get("caption"):
        parts.append(f"Caption: {r['caption']}")
    if r.get("footer"):
        parts.append(f"Footer: {r['footer']}")
    # `Space:` used to be passed in here. It is a target now: feeding it made
    # the model depend at serve time on a field only luna could produce, and
    # put the answer in the header of every example.
    parts.append("")
    parts.append(r["table_serialised"])
    return "\n".join(parts)


def build(r):
    """Train in the format the model is served in.

    Tokenising raw text throws away the template the model already knows, makes
    the fine-tune relearn the input convention from scratch, and forces the
    terminator to be appended by hand -- which is how v1 came to emit
    <|im_end|> while generation watched for <|endoftext|>.

    No truncation: the rebuild dropped pairs that do not fit, because cutting a
    table while keeping its full target teaches the model to emit coordinates
    it cannot see.
    """
    text = tok.apply_chat_template(
        [{"role": "user", "content": r.get("prompt") or document(r)}],
        template=r.get("template") or TEMPLATE, tokenize=False,
        add_generation_prompt=True, enable_thinking=False)
    p_ids = tok(text, add_special_tokens=False)["input_ids"]
    t_ids = tok(r["target_json"], add_special_tokens=False)["input_ids"] + [tok.eos_token_id]
    return p_ids + t_ids, [-100] * len(p_ids) + t_ids


class Pairs(Dataset):
    def __init__(self, path, limit=0, max_tokens=0):
        self.rows = [json.loads(l) for l in Path(path).read_text().split("\n") if l.strip()]
        if max_tokens:
            keep = [r for r in self.rows if int(r.get("n_tokens", 0)) <= max_tokens]
            self.dropped = len(self.rows) - len(keep)
            self.rows = keep
        else:
            self.dropped = 0
        if limit:
            self.rows = self.rows[:limit]

    def __len__(self):
        return len(self.rows)

    def __getitem__(self, i):
        return build(self.rows[i])


def collate(batch):
    m = max(len(x[0]) for x in batch)
    pad = tok.pad_token_id or 0
    ids = torch.full((len(batch), m), pad, dtype=torch.long)
    lab = torch.full((len(batch), m), -100, dtype=torch.long)
    att = torch.zeros((len(batch), m), dtype=torch.long)
    for i, (a, b) in enumerate(batch):
        ids[i, : len(a)] = torch.tensor(a)
        lab[i, : len(b)] = torch.tensor(b)
        att[i, : len(a)] = 1
    return ids, lab, att


ds = Pairs(args.data, args.limit, args.max_tokens)
ds.rows.sort(key=lambda r: -int(r.get("n_tokens", 0)))
if ds.dropped:
    log(f"  dropped {ds.dropped} pairs over {args.max_tokens:,} tokens; "
        f"longest kept {int(ds.rows[0].get('n_tokens', 0)):,}")
if args.probe:
    # Probe the worst case only: if the longest examples fit, everything fits.
    ds.rows = ds.rows[: args.probe * args.accum * max(world, 1)]
else:
    # No reordering. DistributedSampler(shuffle=True) calls randperm over the
    # whole dataset, so the order here is ignored -- the first run's
    # longest-first warm-up did nothing except duplicate 64 examples. The
    # worst case is exercised explicitly below instead.
    longest = ds.rows[0]
    random.Random(0).shuffle(ds.rows)
sampler = DistributedSampler(ds, shuffle=not args.probe, drop_last=True) if world > 1 else None
dl = DataLoader(ds, batch_size=1, sampler=sampler, shuffle=sampler is None and not args.probe,
                collate_fn=collate, num_workers=2, pin_memory=True)
log(f"  {len(ds):,} pairs, {world} cards, accum={args.accum}")

bnb = BitsAndBytesConfig(load_in_4bit=True, bnb_4bit_quant_type="nf4",
                         bnb_4bit_compute_dtype=torch.bfloat16,
                         bnb_4bit_use_double_quant=True)
model = AutoModelForImageTextToText.from_pretrained(
    args.model, quantization_config=bnb, dtype=torch.bfloat16, device_map={"": local_rank})
for holder in (model, getattr(model, "model", None)):
    if holder is None:
        continue
    for attr in ("visual", "vision_tower", "vision_model"):
        if getattr(holder, attr, None) is not None:
            setattr(holder, attr, None)
for p in model.parameters():
    p.requires_grad_(False)
model.gradient_checkpointing_enable(gradient_checkpointing_kwargs={"use_reentrant": False})
model.enable_input_require_grads()
model.config.use_cache = False

ATTN = ["q_proj", "k_proj", "v_proj", "o_proj"]
MLP = ["gate_proj", "up_proj", "down_proj"]
MIXER = ["in_proj_qkv", "in_proj_z", "in_proj_b", "in_proj_a", "out_proj"]
targets = ATTN + MLP + ([] if args.no_linear_attn else MIXER)
rank_pattern = {m: args.mlp_rank for m in MLP}
rank_pattern.update({m: args.attn_rank for m in ATTN})
# in_proj_b and in_proj_a map 2560 -> 32. At r=16 the adapter costs 41,472
# against a full matrix of 81,920 -- half the price of simply training it, and
# no real rank restriction. r=4 is an actual low-rank approximation.
rank_pattern.update({m: 4 for m in ("in_proj_b", "in_proj_a")})
alpha_pattern = {k: v * 2 for k, v in rank_pattern.items()}

if args.init_from:
    # Continue an existing adapter. get_peft_model() would build a fresh one
    # with B=0, discarding everything the previous run learned.
    from peft import PeftModel
    model = PeftModel.from_pretrained(model, args.init_from, is_trainable=True)
    log(f"  continuing from {args.init_from}")
else:
    model = get_peft_model(model, LoraConfig(
        r=args.rank, lora_alpha=args.rank * 2, lora_dropout=args.dropout,
        bias="none", task_type="CAUSAL_LM", target_modules=targets,
        rank_pattern=rank_pattern, alpha_pattern=alpha_pattern))

# Parameters LoRA cannot reach. A_log and dt_bias set the decay and write
# strength of the recurrent state -- how far back a coordinate row can see the
# banner that groups it -- and are 1,536 numbers in total.
DIRECT = ("A_log", "dt_bias", "conv1d.weight", "norm.weight")
direct = []
if not args.no_unfreeze:
    for n, p in model.named_parameters():
        if "lora_" in n or "vis" in n:
            continue
        if any(n.endswith(d) for d in DIRECT):
            p.requires_grad_(True)
            direct.append((n, p))
    if not direct:
        raise SystemExit("no tensor matched DIRECT -- the unfreeze would be silent")
    # A_log and dt_bias are 768 numbers each in bf16, whose 8-bit mantissa gives
    # ~0.008 relative precision. At lr/10 every Adam step is ~1e-5 relative and
    # rounds to zero on write: after 100 steps a first run left them bit-identical
    # to the base model, 0 of 768 heads moved. fp32 makes the update land, and
    # they take the full learning rate -- being few and slow is why they were
    # damped, but the damping was what silenced them.
    #
    # The norms were silenced the same way, and were missed because they kept
    # their damping. Their values sit near 1, so one bf16 step is 2e-3 to 9e-3
    # while lr/10 moves them 1e-5: over v13's first 400 steps q_norm, k_norm,
    # linear_attn.norm and the final norm were bit-identical, while conv1d --
    # damped alike but holding values near 0.03, and so 30x finer steps --
    # moved 8.6 of its own. Both norm classes cast the output back to the input
    # dtype (Qwen3_5RMSNorm already promotes its weight), so fp32 here changes
    # only what the optimizer can write. conv1d cannot be promoted the same
    # way -- the fused causal_conv1d kernel takes bf16 only -- so it gets an
    # fp32 master below instead. It was NOT spared: over 50 steps of v14,
    # 75.3% of its elements were bit-identical between consecutive saves.
    for n, q in direct:
        if n.endswith(("A_log", "dt_bias", "norm.weight")):
            q.data = q.data.float()

# save_pretrained keeps only PEFT parameters, so the unfrozen base tensors are
# written beside the adapter and have to be read back the same way. Done after
# the fp32 cast so the dtypes already match.
if args.init_from and direct:
    saved = torch.load(Path(args.init_from) / "direct.pt", map_location="cpu")
    n_restored = 0
    for n, q in direct:
        if n in saved and saved[n].shape == q.shape:
            with torch.no_grad():
                q.copy_(saved[n].to(q.dtype))
            n_restored += 1
    log(f"  restored {n_restored}/{len(direct)} direct tensors")
    if n_restored < len(direct):
        raise SystemExit("direct.pt did not cover every unfrozen tensor")

model.train()
lora_params = [p for n, p in model.named_parameters() if p.requires_grad and "lora_" in n]
direct_params = [p for _, p in direct]
log(f"  lora {sum(p.numel() for p in lora_params)/1e6:.1f}M"
    f"   direct {sum(p.numel() for p in direct_params)/1e6:.3f}M over {len(direct)} tensors"
    f"  dtypes {sorted({str(p.dtype).replace('torch.','') for p in direct_params})}")
log("  state tensors (A_log, dt_bias): %d at full lr, in %s"
    % (sum(1 for n, _ in direct if n.endswith(('A_log', 'dt_bias'))),
       {str(q.dtype).replace('torch.', '') for n, q in direct if n.endswith(('A_log', 'dt_bias'))}))


def save_ckpt(d: Path):
    """`save_pretrained` keeps only PEFT parameters -- the directly-unfrozen
    base tensors would be dropped, and the model would silently reload without
    them. They are written beside the adapter."""
    peft_model.save_pretrained(d)
    if direct:
        torch.save({n: p.detach().cpu() for n, p in direct}, d / "direct.pt")

peft_model = model
inner = peft_model.base_model.model
core = inner.model.language_model if hasattr(inner.model, "language_model") else inner.model
fused = LigerFusedLinearCrossEntropyLoss()

# The statistic type is ONE token of a ~60-token target, so a wrong type costs
# under 2% of the example's loss and answering with the majority class is very
# nearly free. v14 duly said "T" for 86% of points against 66% in its own
# training data, and where a table header adjudicated a disagreement with luna
# it was right 5.7% of the time against luna's 45.8%. Scaling that one position
# makes the error expensive enough to be worth reading the header for.
#
# Liger's own `ce_weight` is per CLASS, so it would also fire on every bare "T"
# or "R" inside an analysis name -- 88.4% of the weighted mass would land on
# the type slot and the rest would scatter. Per-token losses and a positional
# mask put all of it in the right place.
#
# The type slot is exactly  ,"  X  ",  == OPEN, one of STAT, CLOSE.
OPEN_ID, CLOSE_ID = 1288, 487
# D and G joined the schema in v21 (Cohen's d, Hedges' g) and were missing
# here for that whole run, so the two rarest kinds -- 1.6% and 0.8% of
# points, and the only ones with no curated support at all -- were the only
# ones NOT up-weighted. Backwards: least data, least loss pressure.
STAT_IDS = torch.tensor([51, 57, 37, 47, 49, 33, 35, 38],
                        device="cuda")  # T Z F P R B D G
fused_tok = (LigerFusedLinearCrossEntropyLoss(reduction="none")
             if args.stat_weight != 1.0 else None)


def loss_of(h, lab):
    """Weighted mean over the unmasked positions. At --stat-weight 1 this is
    bit-identical to the plain fused mean; the weights normalise by their own
    sum, so the gradient scale -- and therefore the learning rate -- holds."""
    x = h[:, :-1, :].reshape(-1, h.size(-1))
    flat = lab[:, 1:].reshape(-1)
    if fused_tok is None:
        return fused(inner.lm_head.weight, x, flat)
    per = fused_tok(inner.lm_head.weight, x, flat)   # 0 where label is -100
    m = torch.isin(flat, STAT_IDS)
    m[1:] &= flat[:-1] == OPEN_ID
    m[:-1] &= flat[1:] == CLOSE_ID
    m[0] = m[-1] = False
    w = torch.where(m, args.stat_weight, 1.0).to(per.dtype)
    w = w * (flat != -100)
    return (per * w).sum() / w.sum().clamp(min=1.0)

if not args.probe:
    # OOM canary, before the DDP wrap. DistributedSampler(shuffle=True) permutes
    # the whole dataset, so ordering the rows longest-first does nothing -- the
    # first run's warm-up only duplicated 64 examples. Pushing the single
    # longest pair through here fails in seconds instead of whenever the
    # sampler deals it. It runs before DDP so no reducer hook fires without a
    # matching forward.
    ci, cl = build(longest)
    ch = core(input_ids=torch.tensor([ci], device="cuda")).last_hidden_state
    fused(inner.lm_head.weight,
          ch[:, :-1, :].reshape(-1, ch.size(-1)),
          torch.tensor([cl], device="cuda")[:, 1:].reshape(-1)).backward()
    for _p in list(lora_params) + list(direct_params):
        _p.grad = None
    del ch
    torch.cuda.empty_cache()
    log(f"  canary ok: {len(ci):,} tokens, peak "
        f"{torch.cuda.max_memory_allocated()/2**20:,.0f} MiB")
    torch.cuda.reset_peak_memory_stats()

if world > 1:
    model = DDP(model, device_ids=[local_rank], find_unused_parameters=False,
                gradient_as_bucket_view=True)
# Three groups: the adapters, the state-decay tensors at full rate, and the
# convolutions and norms damped, since those act on every token.
state = [q for n, q in direct if n.endswith(("A_log", "dt_bias"))]
rest = [q for n, q in direct if not n.endswith(("A_log", "dt_bias"))]

# bf16 carries 8 mantissa bits, so the smallest change representable in a
# weight w is about 0.004*w. conv1d's values sit near 0.03, where that floor is
# ~1e-4, while an Adam step is lr-sized: 4e-5 at lr/10 and 4e-4 at full rate.
# Most updates therefore landed on a value that rounded straight back, and
# 75.3% of the tensor was bit-identical between consecutive v14 saves. The
# parameter has to stay bf16 for the fused kernel, so the optimizer is given an
# fp32 copy to accumulate into and the bf16 parameter mirrors it after each
# step -- ordinary mixed-precision master weights.
masters = []
if not args.no_conv_master:
    conv = [q for n, q in direct if n.endswith("conv1d.weight")]
    for q in conv:
        m = q.detach().float().clone().requires_grad_(False)
        masters.append((q, m))
    if masters:
        rest = [q for q in rest if not any(q is c for c in conv)]
        rest = rest + [m for _, m in masters]
        log(f"  conv1d: {len(masters)} tensors on fp32 master weights")

groups = [{"params": lora_params, "lr": args.lr}]
if state:
    groups.append({"params": state, "lr": args.lr})
if rest:
    groups.append({"params": rest, "lr": args.lr / args.slow_lr_div})
opt = torch.optim.AdamW(groups, weight_decay=0.01, betas=(0.9, 0.95))
steps = args.probe or int(len(dl) * args.epochs / args.accum)
if args.sched == "decay":
    # A continuation starts from a converged solution. OneCycle would ramp the
    # rate back to --lr and undo it; this only anneals down.
    sched = torch.optim.lr_scheduler.CosineAnnealingLR(
        opt, T_max=max(steps, 1), eta_min=0.0)
else:
    sched = torch.optim.lr_scheduler.OneCycleLR(
        opt, max_lr=[g["lr"] for g in groups], total_steps=max(steps, 1),
        pct_start=0.03, anneal_strategy="cos")
log(f"  schedule: {args.sched}")
log(f"  {steps:,} optimizer steps planned")

# Only rank 0 logs: every rank sees the same loss, and four writers to one
# sqlite file is a race for no extra information.
track = main and not args.probe and not args.no_trackio
if track:
    trackio.init(project=args.trackio_project,
                 name=args.run_name or Path(args.out).name,
                 config={k: v for k, v in vars(args).items()
                         if not k.startswith("trackio")} |
                        {"steps": steps, "world": world,
                         "examples": len(ds)})

Path(args.out).mkdir(parents=True, exist_ok=True)
t0 = time.time()
step = seen = 0
running = []
done = False
for epoch in range(math.ceil(args.epochs)):
    if sampler:
        sampler.set_epoch(epoch)
    for i, (ids, lab, att) in enumerate(dl):
        ids, lab = ids.cuda(non_blocking=True), lab.cuda(non_blocking=True)
        att = att.cuda(non_blocking=True)
        h = core(input_ids=ids, attention_mask=att).last_hidden_state
        loss = loss_of(h, lab)
        (loss / args.accum).backward()
        running.append(loss.item())
        seen += ids.numel()
        if (i + 1) % args.accum == 0:
            def _norm(ps):
                gs = [p.grad.detach().norm() for p in ps if p.grad is not None]
                return torch.norm(torch.stack(gs)) if gs else torch.tensor(0.0)
            gl, gd = _norm(lora_params), _norm(direct_params)
            torch.nn.utils.clip_grad_norm_(lora_params + direct_params, 1.0)
            # The gradient is produced on the bf16 parameter that the model and
            # DDP actually use; the optimizer holds the fp32 copy, so the two
            # are joined here and the result written back after the step.
            for _q, _m in masters:
                _m.grad = None if _q.grad is None else _q.grad.detach().float()
            opt.step(); sched.step(); opt.zero_grad(set_to_none=True)
            for _q, _m in masters:
                _q.data.copy_(_m.data)
                _q.grad = None
            step += 1
            if args.probe:
                log(f"  probe step {step}/{steps}  loss {loss.item():.4f}  "
                    f"|g_lora| {gl:.4f}  |g_direct| {gd:.6f}  "
                    f"peak {torch.cuda.max_memory_allocated()/2**20:,.0f} MiB")
            elif step % args.log_every == 0:
                el = time.time() - t0
                mean_loss = sum(running) / len(running)
                log(f"  step {step:>5}/{steps}  loss {mean_loss:.4f}  "
                    f"lr {sched.get_last_lr()[0]:.2e}  {seen*world/el:,.0f} tok/s  {el/60:.1f}m")
                if track:
                    # |g_direct| is the one worth watching: when it rounds to
                    # zero the delta-net decay parameters have stopped moving,
                    # which a loss curve does not show.
                    trackio.log({"loss": mean_loss,
                                 "lr": sched.get_last_lr()[0],
                                 "grad_norm/lora": gl.item(),
                                 "grad_norm/direct": gd.item(),
                                 "tokens_per_s": seen * world / el,
                                 "peak_mib": torch.cuda.max_memory_allocated() / 2 ** 20,
                                 "step": step, "epoch": step * args.accum / max(len(dl), 1)})
                running = []
            if main and not args.probe and step % args.save_every == 0:
                save_ckpt(Path(args.out) / f"step-{step}")
            if step >= steps:
                done = True
                break
    if done:
        break

if args.probe:
    log(f"  PEAK {torch.cuda.max_memory_allocated()/2**20:,.0f} MiB of "
        f"{torch.cuda.get_device_properties(local_rank).total_memory/2**20:,.0f} MiB")
    if direct_params and all(p.grad is None for p in direct_params):
        log("  WARNING: no gradient reached the directly-unfrozen tensors")
elif main:
    save_ckpt(Path(args.out) / "final")
    log(f"  done in {(time.time()-t0)/3600:.2f}h -> {args.out}/final")
if track:
    trackio.finish()
if world > 1:
    dist.destroy_process_group()
